from fractions import Fraction
import math


def _exact(value):
    if isinstance(value, Fraction):
        return value
    return Fraction(str(value))


def _display(value):
    if value.denominator == 1:
        return int(value)
    return str(value)


def solve_transport(demand_tonnes, elevator_capacity_tonnes, rocket_capacity_kg, rocket_cost, cost_per_tonne):
    demand = _exact(demand_tonnes)
    elevator_capacity = _exact(elevator_capacity_tonnes)
    rocket_capacity = _exact(rocket_capacity_kg) / 1000
    launch_cost = _exact(rocket_cost)
    unit_cost = _exact(cost_per_tonne)

    if demand < 0 or elevator_capacity < 0:
        raise ValueError('Demand and elevator capacity must be nonnegative.')
    if rocket_capacity <= 0:
        raise ValueError('Rocket capacity must be positive.')
    if launch_cost <= 0 or unit_cost <= 0:
        raise ValueError('Costs must be positive.')

    minimum_launches = max(0, math.ceil((demand - elevator_capacity) / rocket_capacity))
    maximum_launches = max(0, math.ceil(demand / rocket_capacity))
    candidates = []

    for launches in range(minimum_launches, maximum_launches + 1):
        elevator_tonnes = max(Fraction(0), demand - rocket_capacity * launches)
        cost = unit_cost * elevator_tonnes + launch_cost * launches
        candidates.append((cost, launches, elevator_tonnes))

    minimum_cost = min(cost for cost, _, _ in candidates)
    return [
        {
            'e_tonnes': _display(elevator_tonnes),
            'launches': launches,
            'cost': _display(cost),
        }
        for cost, launches, elevator_tonnes in candidates
        if cost == minimum_cost
    ]

